<?php require_once 'config/db.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: write.php');exit;}function clean($v){return trim($v??'');}$title=clean($_POST['title']);$author=clean($_POST['author']);$email=clean($_POST['email']);$excerpt=clean($_POST['excerpt']);$body=clean($_POST['body']);$color=in_array($_POST['color']??'coral',['coral','blue','green','purple','yellow'],true)?$_POST['color']:'coral';if($title===''||$author===''||$body==='')die('Required fields are missing.');$q=$pdo->prepare("INSERT INTO stories(title,author,email,excerpt,body,color,status,created_at) VALUES(?,?,?,?,?,?, 'pending', NOW())");$q->execute([$title,$author,$email,$excerpt,$body,$color]);header('Location: write.php?sent=1');